/* What a scheduled post or a draft carries (round 27), run after part 194. The people who run a community can now schedule a post, or keep a draft, with everything Post would send now: pictures, a video, files, GIFs, videos by link, a link card and a poll. Two new columns on `community_scheduled_posts`: `media`, the same list a post keeps in `community_feed_posts.media` (an empty list by default, at most 40 entries and 64 KB), and `poll`, a poll's question, choices, whether several can be picked, and how many days it runs once the post goes up (null when there is none, at most 16 KB). The table stays server only, as part 194 made it: only the service role reads and writes it, after the app's checks (the media is checked as a post's when it is saved and again, as its author, when it goes up). No existing row changes: every scheduled post and draft keeps its words and gets an empty list and no poll. Until it runs, scheduling works as before with words only, and the writer says this part is needed for a post that carries something. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_scheduled_posts') IS NULL THEN RAISE NOTICE 'scheduled post media: there is no community_scheduled_posts table, run part 194 first.'; RETURN; END IF; ALTER TABLE public.community_scheduled_posts ADD COLUMN IF NOT EXISTS media jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.community_scheduled_posts ADD COLUMN IF NOT EXISTS poll jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_scheduled_posts_media_check' AND conrelid = 'public.community_scheduled_posts'::regclass) THEN ALTER TABLE public.community_scheduled_posts ADD CONSTRAINT community_scheduled_posts_media_check CHECK (jsonb_typeof(media) = 'array' AND jsonb_array_length(media) <= 40 AND octet_length(media::text) <= 65536); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_scheduled_posts_poll_check' AND conrelid = 'public.community_scheduled_posts'::regclass) THEN ALTER TABLE public.community_scheduled_posts ADD CONSTRAINT community_scheduled_posts_poll_check CHECK (poll IS NULL OR (jsonb_typeof(poll) = 'object' AND octet_length(poll::text) <= 16384)); END IF; END $do$;
notify pgrst, 'reload schema';
